/**
 * @pify/skills — the skills pi has loaded, what they cost, and which ones fire.
 *
 * pi already finds skills, formats them into the system prompt, and runs
 * `/skill:name`. What it does not do is tell you what that surface costs or
 * whether any of it earns the charge — and a subscribed collection is easy to
 * grow and impossible to audit by reading transcripts.
 *
 * Nothing here is estimated where it can be measured. Cost comes from pi's own
 * `formatSkillsForPrompt`, the same function that builds the block it sends.
 * Firing is counted from the two ways a skill is actually invoked: pi's prompt
 * tells the model to READ the skill's file when the task matches, so a read of
 * that path is a model invocation, and `/skill:name` is the explicit one.
 *
 * The extension adds nothing to the prompt. Measuring a cost by adding to it
 * would be its own joke.
 */
import {
  formatSkillsForPrompt,
  getAgentDir,
  loadSkills,
  type ExtensionAPI,
  type ExtensionContext,
  type Skill,
} from "@earendil-works/pi-coding-agent";

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { basename, dirname, join } from "node:path";

import { buildInventory, type Inventory, type SkillLike } from "../src/inventory.ts";
import {
  commitLedger,
  mergeLedgers,
  parseLedger,
  record,
  skillForCommand,
  skillForRead,
  type Ledger,
} from "../src/ledger.ts";
import { checkSkill } from "../src/spec.ts";
import {
  danglingReferences,
  declaredRequires,
  extractReferences,
  shadowedSkills,
  type DiagnosticLike,
} from "../src/graph.ts";
import {
  formatCheck,
  formatCost,
  formatOverview,
  formatUnused,
  parseRoute,
  type CheckedSkill,
} from "../src/format.ts";

type UiContext = ExtensionContext;

export default function skillsExtension(pi: ExtensionAPI) {
  let skills: Skill[] = [];
  let inventory: Inventory | null = null;
  let ledger: Ledger = {};
  /** Firings recorded this session but not yet folded into the file on disk. */
  let pending: Ledger = {};
  let ledgerFile: string | null = null;
  /** pi reports name collisions and then carries on with the winner. */
  let diagnostics: DiagnosticLike[] = [];
  /**
   * True once before_agent_start has handed us the exact set pi loaded. Until
   * then the inventory is a disk-scan approximation and is labelled as such.
   */
  let measured = false;

  /** The YAML block between the leading and closing `---` fences, if any. */
  function frontmatterOf(text: string): string {
    const lines = text.split(/\r?\n/);
    if (lines[0]?.trim() !== "---") return "";
    const end = lines.indexOf("---", 1);
    return end === -1 ? "" : lines.slice(1, end).join("\n");
  }

  /**
   * One ledger per project, keyed the way the rest of the suite keys
   * per-project state. Skills are mostly global, but whether a skill earns its
   * place is a question about the work — and the work is the project.
   */
  function resolveLedger(cwd: string): string {
    const key = createHash("sha256").update(cwd.toLowerCase()).digest("hex").slice(0, 12);
    return join(getAgentDir(), "pify-skills", `${key}.json`);
  }

  function loadLedger(): void {
    if (!ledgerFile) return;
    try {
      ledger = parseLedger(readFileSync(ledgerFile, "utf8"));
    } catch {
      ledger = {};
    }
  }

  function saveLedger(): void {
    if (!ledgerFile) return;
    if (Object.keys(pending).length === 0) return;
    try {
      // Re-read and merge whatever another session wrote since we loaded, then
      // swap the file in atomically. A plain overwrite is last-writer-wins: two
      // sessions racing here would erase each other's counts, and a crash
      // mid-write would truncate the file.
      ledger = commitLedger(ledgerFile, pending);
      pending = {};
    } catch {
      // A ledger that cannot be written costs a count, never a turn. Keep the
      // pending delta so the next save can still flush it.
    }
  }

  /**
   * Rebuild the inventory from a concrete skill list — the one thing this
   * package has to get right. After the first request the list comes from pi
   * itself (before_agent_start); before it, from the disk-scan fallback.
   */
  function adopt(list: Skill[]): void {
    try {
      skills = list;
      inventory = buildInventory(
        skills as unknown as SkillLike[],
        (subset) => formatSkillsForPrompt(subset as unknown as Skill[]),
      );
    } catch {
      skills = [];
      inventory = null;
    }
  }

  /**
   * Re-run pi's loader. Two things need it and nothing else does.
   *
   * Collision diagnostics are not carried on before_agent_start, so
   * `shadowedSkills` can only come from here. And before the first request there
   * is no measured set to show, so this is the fallback for `/skills`.
   *
   * But this call is NOT how pi resolves skills: with `includeDefaults: true`
   * and no `skillPaths` it sees only `<agentDir>/skills` and `<cwd>/.pi/skills`,
   * never packages or `.agents/skills` (pi hands those to loadSkills as a
   * resolved path list this call does not have). So once the authoritative set
   * has arrived it must not overwrite it — hence the `measured` guard.
   */
  function rediscover(ctx: UiContext): void {
    try {
      const loaded = loadSkills({
        cwd: ctx.cwd,
        agentDir: getAgentDir(),
        skillPaths: [],
        includeDefaults: true,
      });
      diagnostics = (loaded.diagnostics ?? []) as DiagnosticLike[];
      if (!measured) adopt(loaded.skills);
    } catch {
      diagnostics = [];
      if (!measured) {
        skills = [];
        inventory = null;
      }
    }
  }

  function note(name: string, by: "model" | "command"): void {
    const firing = { name, by, at: Date.now() };
    ledger = record(ledger, firing);
    pending = record(pending, firing);
    saveLedger();
  }

  // ── Counting what fires ──────────────────────────────────────────────

  pi.on("tool_call", async (event, ctx) => {
    // pi's own skills prompt says: read the skill's file when the task
    // matches. That read IS the invocation.
    if ((event as { toolName?: string }).toolName !== "read") return undefined;
    const path = (event as { input?: { path?: unknown } }).input?.path;
    if (typeof path !== "string") return undefined;
    // The model may read a skill by a path relative to cwd; resolve it there so
    // it still matches the absolute path pi loaded the skill from.
    const name = skillForRead(path, skills, ctx.cwd);
    if (name) note(name, "model");
    return undefined;
  });

  pi.on("input", async (event) => {
    // The explicit half. Extension-sourced input is this suite talking to
    // itself and is not a person choosing a skill.
    if ((event as { source?: string }).source === "extension") return undefined;
    const text = (event as { text?: unknown }).text;
    if (typeof text !== "string") return undefined;
    const name = skillForCommand(text);
    if (name) note(name, "command");
    return undefined;
  });

  // ── Lifecycle ────────────────────────────────────────────────────────

  pi.on("before_agent_start", async (event) => {
    // pi hands us the exact skill set it just built into the system prompt —
    // packages, .agents/skills, per-resource enable/disable, project trust and
    // --skill/--no-skills all already resolved. That is the authoritative list;
    // re-discovering it ourselves only ever reproduces a subset. It fires once
    // per request, so adopting it here also tracks /reload with no captured ctx.
    const list =
      (event as { systemPromptOptions?: { skills?: Skill[] } }).systemPromptOptions?.skills ?? [];
    measured = true;
    adopt(list);
    return undefined;
  });

  pi.on("session_start", async (_event, ctx) => {
    ledgerFile = resolveLedger(ctx.cwd);
    loadLedger();
    // A fallback so /skills has an answer before the first request; the real set
    // replaces it on before_agent_start.
    rediscover(ctx);
  });

  // ── Command ──────────────────────────────────────────────────────────

  pi.registerCommand("skills", {
    description: "What skills are loaded, what they cost per request, and which ones fire: /skills [cost|unused|check]",
    handler: async (args, ctx) => {
      if (!ctx.hasUI) return;
      const route = parseRoute(args ?? "");
      if (route.kind === "error") {
        ctx.ui.notify(route.message, "warning");
        return;
      }

      // Before the first request there is no measured set, so fall back to a
      // disk scan. After it, the measured set is authoritative — a rescan would
      // report skills pi has not loaded until the next /reload — so leave it be.
      if (!measured) rediscover(ctx);
      if (!inventory) {
        ctx.ui.notify("Could not read the loaded skills.", "error");
        return;
      }

      // Another session's firings are merged on disk (commitLedger re-reads and
      // folds), but our in-memory view only moves when we fire a skill ourselves.
      // Re-read so the answer reflects every session, not just this one.
      if (ledgerFile) {
        try {
          ledger = mergeLedgers(parseLedger(readFileSync(ledgerFile, "utf8")), pending);
        } catch {
          // A render is never worth a throw; fall back to the in-memory view.
        }
      }

      switch (route.kind) {
        case "overview":
          ctx.ui.notify(formatOverview(inventory, ledger, Date.now(), measured), "info");
          return;
        case "cost":
          ctx.ui.notify(formatCost(inventory), "info");
          return;
        case "unused":
          ctx.ui.notify(formatUnused(inventory, ledger), "info");
          return;
        case "check": {
          // Collision diagnostics ride on the loader, not on before_agent_start,
          // so refresh them here. When measured this leaves the inventory and the
          // skill list untouched (rediscover only re-adopts before the first turn).
          if (measured) rediscover(ctx);

          const bodies = new Map<string, string>();
          const checked: CheckedSkill[] = skills.map((skill) => {
            let text = "";
            try {
              text = readFileSync(skill.filePath, "utf8");
            } catch {
              return {
                name: skill.name,
                filePath: skill.filePath,
                problems: [{ level: "error" as const, message: "could not be read" }],
              };
            }
            bodies.set(skill.name, text);
            return {
              name: skill.name,
              filePath: skill.filePath,
              // Pass the file name so a bare <root>/<name>.md skill (which pi
              // loads) is reported as off-spec, not as a phantom directory mismatch.
              problems: checkSkill(text, basename(dirname(skill.filePath)), basename(skill.filePath)),
            };
          });

          // Resolve against what pi LOADED, not what is on disk: a skill that
          // lost a name collision is missing as far as the model is concerned.
          const loadedNames = new Set(skills.map((s) => s.name));
          const dangling = danglingReferences(
            [...bodies].map(([name, text]) => {
              const frontmatter = frontmatterOf(text);
              return {
                name,
                references: extractReferences(name, text),
                requires: declaredRequires(frontmatter),
              };
            }),
            loadedNames,
          );
          ctx.ui.notify(formatCheck(checked, dangling, shadowedSkills(diagnostics)), "info");
          return;
        }
      }
    },
  });
}
